WITH payload AS (SELECT $archive_payload$[{"id":"867f1df7-2aec-5aea-92d9-3ace30ee7310","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -منجم -ادعاء علم الغيب -إنكار االدعاء-استفتاح الفأل بالقرآن -التعزير بأخذ التعهد على املدعى عليه بعدم تكرار ما","document_number":"33480856","case_number":"32421641","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية بكتاب فضيلة رئيسها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/18","year":"1434","subject":"سحر -منجم -ادعاء علم الغيب -إنكار االدعاء-استفتاح الفأل بالقرآن -التعزير بأخذ التعهد على املدعى عليه بعدم تكرار ما","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33480856:‬تاريخه‪1433/12/18 :‬هـ‬\n                    ‫رقم الدعوى‪32421641:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 34238082:‬تاريخه‪1434/06/12:‬هـ‬\n\n\n ‫ســحر ‪ -‬منجــم ‪ -‬ادعــاء علــم الغيــب ‪ -‬إنــكار االدعاء‪-‬اســتفتاح الفــأل‬\n ‫بالقــرآن ‪ -‬التعزيــر بأخــذ التعهــد علــى املدعــى عليــه بعــدم تكــرار مــا‬\n                                                                     ‫بــدر منــه‪.‬‬\n\n\n\n\n ‫ا يف ســفر الهجــرة‪« :‬مــا‬   ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم ملــا لقــي رج ـ ً‬\n                   ‫اســمك» قــال‪ :‬يزيــد‪ .‬قــال‪« :‬يــا أبــا بكــر يزيــد أمرنــا»‪.‬‬\n ‫‪ .2‬قــال ابــن العربــي رحمــه اهلل‪« :‬وال يجــوز ألحــد مــن خلــق اهلل أن‬\n ‫يتعــرض للغيــب وال يطلبــه فــإن اهلل ســبحانه قــد رفعــه بعــد نبيــه إال‬\n ‫يف الرؤيــا‪ ،‬فــإن قيــل فهــل يجــوز طلــب ذلــك يف املصحــف قلنــا ال يجــوز‬\n ‫فإنــه لــم يكــن املصحــف ليعلــم بــه الغيــب إمنــا بينــت آياتــه ورســمت‬\n ‫كلماتــه ليمنــع عــن الغيــب فــا تشــتغلوا بــه وال يتعــرض أحدكــم لــه‬\n                                                                           ‫أ‪.‬ه ـ ‪28/2‬‬\n ‫‪ .3‬قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل‪« :‬وأمــا اســتفتاح الفــأل يف‬\n ‫املصحــف فلــم ينقــل عــن الســلف فيــه شــيء وقــد تنــازع فيــه املتأخــرون‬\n ‫وذكــر القاضــي أبــو يعلــى فيــه نزاع ـ ًا ذكــر عــن ابــن بطــة أنــه فعلــه‬\n ‫وذكــر عــن غيــره أنــه كرهــه فــإن هــذا ليــس الفــأل الــذي يحبــه رســول‬\n ‫اهلل صلــى اهلل عليــه وســلم فإنــه كان يحــب الفــأل ويكــره الطيــرة» أ‪.‬ه ـ‬\n                                                         ‫مجمــوع الفتــاوى ‪66/23‬‬\n\n\n                                                                                        ‫‪278‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بقــراءة الفــأل للنــزالء وادعاء علم‬\n      ‫الغيــب‪ ،‬وذلــك بعدمــا قــام املدعــى عليــه وهــو (موقــوف علــى ذمــة قضيــة‬\n      ‫أعمال ســحر وشــعوذة) مبمارســة الشــعوذة على النزالء بالسجن‪ ،‬وطلب‬\n      ‫املدعــي العــام النظــر يف القضيــة بالوجــه الشــرعي ‪،‬وبعــرض دعــوى‬\n      ‫املدعــي العــام علــى املدعــى عليــه أنكرهــا‪ ،‬ودفــع بأنــه يقــرأ القــرآن‬\n      ‫يف مصلــى الســجن بعــد صــاة العشــاء ( وجــود إقــرار حتقيقـ ًا للمدعــى‬\n      ‫عليــه مبــا نســب إليــه)‪ ،‬لــذا ثبــت قيــام املدعــى عليــه باســتفتاح الفــأل‬\n      ‫بالقــرآن ومت احلكــم بأخــذ التعهــد علــى املدعــى عليــه بعــدم تكــرار مــا‬\n      ‫بــدر منــه وإفهامــه أن الفــأل الــذي كان يحبــه صلــى اهلل عليــه وســلم‬\n      ‫ال علــى اهلل فيســمع الكلمــة‬   ‫أن يفعــل املــرء أمــر ًا أو يعــزم عليــه متــوك ً‬\n      ‫احلســنة التــي تســره ‪،‬وبعــرض احلكــم علــى الطرفــن اعتــرض عليــه‬\n      ‫املدعــي العــام وطلــب اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع بــه‬\n      ‫املدعــى عليــه ‪،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة‬\n                                                                                    ‫عليــه‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة اجلزئيــة بالقطيف‬\n      ‫بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪32421641‬‬\n      ‫يف ‪1432/9/21‬ه ـ والــواردة بكتــاب ســعادة محافــظ القطيــف بكتابه‬\n      ‫رقــم ‪ 1/5099/4‬يف ‪1431/5/3‬ه ـ حضــر املدعــي العام مبوجب كتاب‬\n      ‫التكليــف رقــم ‪ 1127/8/21‬يف ‪1433/2/10‬ه ـ وادعــى علــى احلاضــر‬\n\n‫‪279‬‬\n\f‫ا عن ‪...‬الســعودي بالســجل‬     ‫معــه ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬وكيـ ً‬\n‫املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل القطيــف‬\n‫ا يف دعواه‪ :‬نفيد فضيلتكم‬          ‫برقــم ‪ 33206003‬يف ‪1433/4/21‬ه ـ قائـ ً‬\n‫بأنــه ورود خطــاب رئيــس قســم ســجن محافظــة القطيــف‪2/21/271/9‬‬\n‫يف ‪1423/8/8‬ه ـ املتضمــن قيــام النزيــل بالســجن لديهــم ‪(....../‬موقــوف‬\n‫علــى ذمــة قضيــة أعمــال ســحر وشــعوذة) مبمارســة الشــعوذة علــى النزالء‬\n‫بالســجن وقــد مت نصحــه مــن قبــل الشــؤون الدينيــة بالســجن إال انــه‬\n‫مصــر علــى عملــه لــذا فــإن التحقيــق توصــل إلــى ان مــا يقــوم بــه املذكــور‬\n‫اســمه أعــاه مــن قــراءة الفــأل للنــزالء وفتحــه للمصحــف ومقولتــه لهــم‬\n‫بأنــه ســوف يحــدث كــذا وكــذا فهــذا ادعــاء بعلــم الغيــب وهــو أمــر‬\n‫مخالــف للعقيــدة وحيــث املذكــور موقــوف بســجن محافظــة القطيــف‬\n‫علــى ذمــة قضيــة ســابقة مــع العلــم بأنــه ال يوجــد لــه ســوابق لــذا نأمــل‬\n‫مــن فضيلتكــم االطــاع والنظــر يف القضيــة بالوجــه الشــرعي هــذا‬\n‫ا‬\n‫مــا ادعــى بــه وبعرضــه علــى املدعــى عليــه وبســؤاله عنــه أجــاب قائ ـ ً‬\n‫مــا ذكــره املدعــي العــام يف دعــواه ضــد موكلــي مــن اتهامــه بادعــاء‬\n‫علــم الغيــب غيــر صحيــح إذ أن موكلــي يعتقــد أنــه ال يعلــم الغيــب إال‬\n‫اهلل وغايــة مــا كان يفعلــه موكلــي هــو قــراءة القــرآن يف املصلــى الــذي‬\n‫بالســجن إذ بعــد صــاة العشــاء كان يأخــذ املصحــف للتــاوة كمــا‬\n‫كان يأخــذه غيــره ومــا ذكــره املدعــي العــام مــن أن موكلــي كان‬\n‫يقــرأ الفــأل بالقــرآن غيــر صحيــح أيضـ ًا هــذا مــا أجــاب بــه وبــرده علــى‬\n‫ا الصحيــح مــا جــاء يف دعــواي هــذا مــا أفــاد‬     ‫املدعــي العــام أفــاد قائ ـ ً‬\n‫ا بينتــي مــا جــاء‬\n                   ‫بــه وبســؤاله عــن بينتــه علــى طبــق دعــواه أجــاب قائ ـ ً‬\n‫يف أوراق املعاملــة وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى‬\n\n\n                                                                                         ‫‪280‬‬\n\f      ‫أجوبــة املدعــى عليــه عــن أســئلة التحقيــق املدونــة علــى الصحيفــة رقــم‬\n      ‫‪ 2-1‬مــن ملــف التحقيــق املرفــق باملعاملــة باللفــة رقــم ‪ 7‬وفيــه مــا نصــه‬\n      ‫عنــد حضــور أي شــخص إلــي أقــوم بفتــح القــرآن وأقــرأ لــه اآليــة التــي‬\n      ‫فتــح عليهــا املصحــف بشــكل عشــوائي ويكــون ذلــك فالــه مثــل قيــام‬\n      ‫شــخص باحلضــور إلــي وقمــت بفتــح املصحــف وكانــت اآليــة قولــه تعالــى‬\n      ‫(خذهــا وال تخــف ســنعيدها ســيرتها األولــى) والشــخص ذلــك كان‬\n      ‫مريض ـ ًا وأنــا قلــت لــه بأنــه ســوف تعــود لــه صحتــه وبالفعــل كان ذلــك‬\n      ‫حيــث كان مجنونـ ًا أ‪.‬ه ـ وفيــه مــا نصــه قمــت بــه كثيــر ًا مــع الســجناء‬\n      ‫حيــث إنــي قمــت بــه أكثــر مــن ثالثــن أو أربعــن مــرة أ‪.‬ه ـ وبعرضــه علــى‬\n      ‫ا الصحيــح مــا ذكرتــه يف إجابتــي عــن الدعــوى‬        ‫املدعــى عليــه أفــاد قائـ ً‬\n      ‫هــذا مــا أجــاب بــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار‬\n      ‫املدعــى عليــه مــا نســبه لــه املدعــي العــام يف دعــواه وإلقــرار املدعــى عليــه‬\n      ‫يف أجوبتــه عــن أســئلة التحقيــق باســتفتاح الفــأل باملصحــف وألنــه لــم‬\n      ‫يدفعــه بدفــع مقبــول وقــد قــرر ابــن العربــي رحمــه اهلل يف أحكامــه‬\n      ‫‪ 28/2‬يف مســألة اســتفتاح الفــأل باملصحــف بقولــه وال يجــوز ألحــد مــن‬\n      ‫خلــق اهلل أن يتعــرض للغيــب وال يطلبــه فــإن اهلل ســبحانه قــد رفعــه بعــد‬\n      ‫نبيــه إال يف الرؤيــا فــإن قيــل فهــل يجــوز طلــب ذلــك يف املصحــف قلنــا ال‬\n      ‫يجــوز فإنــه لــم يكــن املصحــف ليعلــم بــه الغيــب إمنــا بينــت آياتــه ورســمت‬\n      ‫كلماتــه ليمنــع عــن الغيــب فــا تشــتغلوا بــه وال يتعــرض أحدكــم لــه‬\n      ‫أ‪.‬ه ـ وقــد ســئل عنهــا شــيخ اإلســام رحمــه اهلل وأجــاب عنهــا بقولــه وأمــا‬\n      ‫اســتفتاح الفــأل يف املصحــف فلــم ينقــل عــن الســلف فيــه شــيء وقــد‬\n      ‫تنــازع يف املتأخــرون وذكــر القاضــي أبــو يعلــى فيــه نزاع ـ ًا ذكــر عــن‬\n      ‫ابــن بطــة أنــه فعلــه وذكــر عــن غيــره أنــه كرهــه فــإن هــذا ليــس الفــأل‬\n\n\n‫‪281‬‬\n\f‫الــذي يحبــه رســول اهلل صلــى اهلل عليــه وســلم فإنــه كان يحــب الفــأل‬\n‫ويكــره الطيــرة أ‪.‬ه ـ مجمــوع الفتــاوى ‪ 66/23‬وألنــه لــم يصاحــب مــا‬\n‫فعلــه املدعــى عليــه أصالــة ادعــاء لعلــم الغيــب وملــا نقــل يف هــذه املســألة‬\n‫مــن نــزاع متقــدم بــن الفعــل والتــرك لــذا وملــا تقــدم فقــد ثبــت لــدي قيــام‬\n‫املدعــى عليــه أصالــة باســتفتاح الفــأل بالقــرآن وقــررت أخــذ التعهــد علــى‬\n‫املدعــى عليــه أصالــة بعــدم تكــرار مــا بــدر منــه وأفهمــت املدعــى عليــه‬\n‫وكالــة أن الفــأل الــذي كان يحبــه صلــى اهلل عليــه وســلم أن يفعــل املــرء‬\n‫ال علــى اهلل فيســمع الكلمــة احلســنة التــي‬      ‫أمــر ًا أو يعــزم عليــه متــوك ً‬\n‫ا فقــال مــا اســمك قــال يزيــد قــال‬‫تســره كمــا لقــي يف ســفر الهجــرة رجـ ً‬\n‫يــا أبــا بكــر يزيــد أمرنــا وأمــا الطيــرة بعكســه فيكــون قــد فعــل أمــر ًا‬\n‫ال علــى اهلل أو يعــزم عليــه فيســمع كلمــة مكروهــة فيتطيــر‬           ‫متــوك ً‬\n‫ويتــرك األمــر وأن املــرء عليــه أن يســلك الســبل املشــروعة يف طلــب اخليــرة‬\n‫يف اســتخارة اخلالــق واستشــارة املخلــوق واالســتدالل باألدلــة الشــرعية‬\n‫التــي تبــن مــا يحبــه اهلل ويرضــاه ومــا يكرهــه وينهــى عنــه وقــد قــرر‬\n‫مــا ذكــر شــيخ اإلســام رحمــه اهلل ولالســتزادة عليــه مطالعــة مــا قــرره‬\n‫يف هــذا الشــأن ففهمــه وبعــرض مــا ذكــر علــى الطرفــن اعتــرض عليــه‬\n‫املدعــي العــام وطلــب اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع بــه‬\n‫املدعــى عليــه وكالــة وســيتم بعــث كامــل املعاملــة حملكمة االســتئناف‬\n‫لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف ‪1433/12/28‬ه ـ وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬احلمــدهلل‬\n‫وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية بكتــاب فضيلــة رئيســها رقــم ‪ 34174567‬يف ‪1434/3/2‬ه‬\n‫املقيــدة يف هــذه احملكمــة برقــم ‪ 34583332‬يف ‪1434/3/7‬ه واحملالــة‬\n\n\n                                                                                         ‫‪282‬‬\n\f      ‫مــن فضيلــة الرئيــس وبرفقهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n      ‫قضــاة الدائــرة اجلزائيــة األولــى رقــم ‪ 3448212‬يف ‪1434/2/26‬ه‬\n      ‫ونصــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫لوحــظ ان فضيلــة القاضــي حكــم يف هــذه القضيــة واملدعــى عليــه لــه‬\n      ‫قضيــه مماثلــه ســجن بســببها فهــل مت احلكــم فيهــا ام ال ملالحظــة مــا‬\n      ‫ذكــر واكمــال الــازم ومــن ثــم اعــادة املعاملــة واهلل املوفــق وصلــى‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/2/24‬ه قاضــي‬\n      ‫اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه رئيــس‬\n      ‫الدائــرة ‪...‬ختمــه وتوقيعــه أ‪.‬ه ـ عليــه فقــد حضــر املدعــي العــام وبعــرض‬\n      ‫مــا جــاء يف قــرار أصحــاب الفضيلــة عليــه أبــرز ورقــة مــن مطبوعــات‬\n      ‫اإلدارة العامــة لألمــن العــام تضمنــت عــرض ‪...‬الســعودي بالســجل‬\n      ‫املدنــي رقــم ‪...‬وأنــه صــدر يف حقــه احلكــم ذو الرقــم ‪ 126/2‬بتاريــخ‬\n      ‫‪1422/8/20‬ه ـ ووقــد تضمــن احلكــم عليــه بجلــده أربعمائــة وتســعني‬\n      ‫جلــدة وســجنه مــدة تســعة أشــهر يف ســحر وشــعوذة هــذا مــا لــزم جواب ـ ًا‬\n      ‫علــى مالحظــة أصحــاب الفضيلــة ولفضيلتهــم فائــق التقديــر واالحتــرام‬\n      ‫وللبيــان حــرر يف ‪1434/5/7‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه أجمعــن ‪ .‬احلمــدهلل وحــده وبعــد لقــد عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف بالدمــام بكتــاب فضيلــة رئيســها رقــم‬\n      ‫‪ 341183019‬يف ‪1434/6/20‬ه ـ املقيــدة يف هــذه احملكمــة برقــم‬\n      ‫‪ 341183019‬يف ‪1434/6/24‬ه ـ واحملالــة مــن فضيلــة الرئيــس وبرفقها‬\n      ‫إعــام احلكــم الصــادر منــي برقــم ‪ 33480856‬يف ‪1433/12/28‬ه ـ‬\n      ‫وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى رقــم‬\n      ‫‪ 34238082‬يف ‪1434/6/12‬ه ـ ونصــه بعــد املقدمــة حيــث ســبق دراســة‬\n\n\n‫‪283‬‬\n\f‫القــرار وصــورة ضبطــه وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n‫وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪ 3448212‬يف‬\n‫‪1434/2/26‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد االجــراء األخيــر‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n‫‪1434/6/11‬ه ـ قاضــي اســتئناف د‪... .‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n‫‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه أ‪.‬ه ـ وللبيــان حــرر يف‬\n‫‪1434/6/24‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                       ‫أجمعــن‪.‬‬\n\n\n\n\n                                                                                     ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":278,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"392a111e74cacd262f1cd3a7dfd989e0412bb6eaf8537933e9fda4ec68ba0944","normalized_text_hash":"c0225e4b383180aa798e658dedebfd1b9560482d35d57cf7ee99aaf1fec3d45c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p278-33480856"},{"id":"521b9817-a7ea-51f9-a87a-6a81f58da0d3","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -حيازة طالسم سحرية -اإلقرار باالدعاء -االكتفاء بإفهام املدعى عليه فضيلة التوحيد أثناء اجللسة.","document_number":"33330091","case_number":"33189347","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/06","year":"1434","subject":"سحر -حيازة طالسم سحرية -اإلقرار باالدعاء -االكتفاء بإفهام املدعى عليه فضيلة التوحيد أثناء اجللسة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33330091:‬تاريخه‪1433/07/06 :‬هـ‬\n                          ‫رقم الدعوى‪33189347:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 3437791:‬تاريخه‪1434/02/16:‬هـ‬\n\n\n       ‫ســحر ‪ -‬حيــازة طالســم ســحرية ‪ -‬اإلقــرار باالدعــاء ‪ -‬االكتفــاء بإفهــام‬\n                                  ‫املدعــى عليــه فضيلــة التوحيــد أثناء اجللســة‪.‬‬\n\n\n\n\n       ‫‪ -‬قولــه تعالــى‪« :‬وننــزل مــن القــران ماهــو شــفاء ورحمــة للمؤمنــن وال‬\n                                     ‫يزيــد الظاملــن إال خســارا» [اإلســراء‪.]82:‬‬\n              ‫‪ -‬قوله صلى اهلل عليه وسلم‪« :‬من تعلق متيمة فال أمت اهلل له»‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بحيازتــه طالســم ســحرية بقصد‬\n       ‫التــداوي وذلــك بعــد القبــض عليــه وتفتيشــه والعثــور معــه يف محفظتــه‬\n       ‫علــى أوراق وقطعــة نحاســية بهــا طالســم ســحرية وقــد أثبــت محضــر‬\n       ‫فحــص املضبوطــات مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر‬\n       ‫أنهــا طالســم ســحرية ‪،‬وطلــب املدعــي العــام احلكــم علــى املدعــى‬\n       ‫عليــه بعقوبــة تعزيريــة ‪،‬وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n       ‫عليــه بواســطة املترجــم صــادق عليهــا وذكــر أنــه يعتقــد أنهــا تفيــد‬\n       ‫يف االستشــفاء مــن األمــراض ‪،‬وجــرى االطــاع علــى محضــر فحــص‬\n       ‫املضبوطــات املتضمــن أن املضبوطــات طالســم ســحرية وألن املدعــى‬\n       ‫عليــه صــادق علــى صحــة دعــوى املدعــي العــام ودفــع بــأن ســبب حيازتــه‬\n\n‫‪285‬‬\n\f‫لهــا هــو اعتقــاده بأنــه تفيــد يف االستشــفاء مــن األمــراض وخلطــورة مــا‬\n‫قــام بــه املدعــى عليــه كــون التعلــق بالطالســم الســحرية واالعتقــاد‬\n‫وتعلــق القلــب بهــا يعتبــر مــن أعظــم الذنــوب خاصــة واملدعــى عليــه مســلم‬\n‫الديانــة ‪،‬لــذا جــرى إفهــام املدعــى عليــه أن مثــل هــذه الطالســم ال‬\n‫تكــون ســببا يف الشــفاء‪ ،‬وإمنــا الشــفاء يكــون باللجوء إلــى اهلل بالدعاء‬\n‫خالصــا وبآيــات القــران الكــرمي ‪،‬وقــرر ناظــر القضيــة االكتفــاء مبــا‬\n‫مت مــن إفهــام املدعــى عليــه مــن فضيلــة التوحيــد أثنــاء اجللســة ‪،‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قنــع بــه وقــرر املدعــي العــام اعتراضــه عليــه‬\n‫وطلــب اســتئناف احلكــم مكتفيــا مبــا ورد يف الئحــة الدعــوى ‪،‬وبعــد‬\n                 ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 33189347‬وتاريــخ ‪1433/03/15‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 33500585‬وتاريــخ ‪1433/3/15‬ه ـ ففــي‬\n‫يــوم االثنــن املوافــق ‪ 1433/06/30‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n‫‪ 02‬حضــر املدعــي العــام ‪...‬وحضــر حلضــوره ‪ ...‬مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ )...‬وادعــى املدعــي العــام قائــا إنــه بتاريــخ ‪1432/6/27‬ه ـ قبــض‬\n‫علــى املدعــى عليــه مــن قبــل دوريــات أمــن الطــرق مبحافظــة األحســاء‬\n‫علــى طريــق ســلوى إثــر اســتيقاف ســيارة مــن نــوع تويوتــا حتمــل اللوحــة‬\n‫رقــم (‪ )...‬بقيــادة الســائق ‪(...‬هنــدي اجلنســية) (لــم يوجــه لــه االتهــام)‬\n‫ويرافقــه املدعــى عليــه وبتفتيشــه عثــر يف محفظتــه علــى أوراق وقطعــة‬\n\n                                                                                    ‫‪286‬‬\n\f      ‫نحاســية بهــا طالســم ســحرية وقــد أثبــت محضــر فحــص املضبوطــات‬\n      ‫مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر أنهــا طالســم‬\n      ‫ســحرية وباســتجواب املدعــى عليــه اعتــرف بصحــة واقعــة القبــض وأن‬\n      ‫املضبوطــات عائــدة لــه بقصــد االستشــفاء بهــا وقــد أســفر التحقيــق‬\n      ‫عــن توجيــه االتهــام لــه بحيــازة طالســم ســحرية بقصــد التــداوي وذلــك‬\n      ‫لألدلــة والقرائــن التالية‪/1:‬إقــراره املنــوه عنــه املصــدق قضائي ـ ًا املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )8‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪)2‬‬\n      ‫‪/2‬محضــر فحــص املضبوطــات املنــوه عنــه واملــدون علــى الصفحــة رقــم‬\n      ‫(‪ )1‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪/3 )20‬محضــر القبــض‬\n      ‫املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )5‬وبالبحــث عمــا إذا كان لــه‬\n      ‫ســوابق لــم يعثــر لــه علــى ســوابق وحيــث إن مــا أقــدم عليــه املذكــور وهــو‬\n      ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره‬\n      ‫هــذه دعــواي وبطلبــي مــن املدعــى عليــه اإلجابــة أجــاب بواســطة املترجــم‬\n      ‫املتعــاون مــع احملكمــة ‪...‬والــذي قــام بــدور الترجمــة مــن العربيــة إلــى‬\n      ‫األرديــة والعكــس قائــا‪ :‬مــا ذكــره املدعــي العــام يف دعــواه صحيــح‬\n      ‫فقــد عثــر يف محفظتــي علــى أوراق وقطعــة نحاســية بها طالســم ســحرية‬\n      ‫كنــت أحوزهــا العتقــادي بأنــه تفيــد يف االستشــفاء مــن األمــراض هــذه‬\n      ‫إجابتــي وبعــد ســماع الدعــوى واإلجابــة جــرى االطــاع علــى محضــر‬\n      ‫فحــص املضبوطــات املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )1‬مــن‬\n      ‫دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪ )20‬فوجــد يتضمــن مــا نصــه‬\n      ‫بعــد املقدمــة‪[ :‬تبــن ان املضبوطــات عبــارة عــن أربــع قصاصــات ورقيــة‬\n      ‫وأربــع رقائــق نحاســية كتــب يف األولــى ونقــش يف الثانيــة أعمــال ســحر‬\n\n\n‫‪287‬‬\n\f‫منهــا مــا يســمى الطلســم الســليماني وهــو ســحر عطــف واســحار أخــرى‬\n‫لــم نتبــن غرضهــا] انتهــى املطلــوب ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومبــا ان املدعــى عليــه صــادق علــى صحــة دعــوى املدعــي‬\n‫العــام واقــر بحيازتــه علــى أوراق وقطعــة نحاســية بهــا طالســم ســحرية‬\n‫ودفــع بــان ســبب حيازتــه لهــا هــو اعتقــاده بأنــه تفيــد يف االستشــفاء مــن‬\n‫األمــراض وال يخفــى خطــورة مــا قــام بــه املدعــى عليــه كــون التعلــق‬\n‫بالطالســم الســحرية واالعتقــاد وتعلــق القلــب بهــا يعتبــر مــن أعظــم‬\n‫الذنــوب خاصــة واملدعــى عليــه مســلم الديانــة لــذا افهمتــه ان مثــل هــذه‬\n‫الطالســم التكــون ســبب يف الشــفاء بــل قــد دعــى النبــي صلــى اهلل عليــه‬\n‫وســلم [مــن تعلــق متيمــة فــا امت اهلل لــه] والشــفاء امنــا يكــون باللجــوء الــى‬\n‫اهلل بالدعــاء خالصــا وبآيــات القــران الكــرمي لقــول اهلل تعالــى يف ســورة‬\n‫االســراء ايــة (‪[ )82‬وننــزل مــن القــران ماهــو شــفاء ورحمــة للمؤمنــن‬\n‫وال يزيــد الظاملــن اال خســارا] وقــررت االكتفــاء بتعليمــه فضيلــة‬\n‫التوحيــد وبعرضــه عليــه قنــع بــه وقــرر املدعــى العــام اعتراضــه عليــه‬\n‫وطلــب اســتئناف احلكــم مكتفيــا مبــاورد يف الئحــة الدعــوى وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                    ‫‪1433/6/30‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االحــد املوافــق ‪1434/1/11‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11.10‬بنــاء علــى ورود املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 331615245‬يف ‪1433/9/11‬ه ـ‬\n‫و برفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة برقــم‬\n‫قــرار ‪ 33400432‬يف ‪1433/9/3‬ه ـ ونــص احلاجــة منــه (وبدراســة القرار‬\n‫وصــور ضبطــه وأوراق املعاملــة لوحــظ أن صــورة الضبــط املرفقــه‬\n\n\n                                                                                          ‫‪288‬‬\n\f      ‫ناقصــة ولــم توقــع مــن قبــل فضيلتــه ويختــم بختمــه اخلــاص ثانيــا قــرر‬\n      ‫فضيلتــه تعليــم املدعــى عليــه التوحيــد وهــذا محــل نظــر حيــث ان ذلــك‬\n      ‫غيــر ممكــن التنفيــذ) عليــه اجيــب اصحــاب الفضيلــة ان مقصــودي‬\n      ‫بالعبــارة هــو االكتفــاء مبــا مت تعليمــه بــه يف أثنــاء اجللســة والن العبــارة‬\n      ‫قــد تســبب لبســا ال ســيما أثنــاء التنفيــذ فقــد رجعــت عــن اجلملــة التــي‬\n      ‫نصهــا (قــررت االكتفــاء بتعليمــه فضيلــة التوحيــد) وصحــة العبــارة هــو‬\n      ‫قــررت االكتفــاء مبــا مت إفهامــه بــه مــن فضيلــة التوحيــد أثنــاء اجللســة‬\n      ‫املنعقــدة بتاريــخ ‪1433/6/30‬ه ـ وســوف يتــم التنبيــه ملثــل هــذا األمــر‬\n      ‫مســتقبال بــإذن اهلل تعالــى هــذا وأمــرت بإحلــاق مــا مت ضبطــه بالقــرار‬\n      ‫وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم ‪ .‬حــرر يف ‪1434/1/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/235501‬ج‪ 2‬وتاريــخ ‪1434/1/27‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n      ‫‪ 331704343‬وتاريــخ ‪1434/1/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .../‬املســجل برقــم ‪33330091‬‬\n      ‫وتاريــخ ‪1433/7/6‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪(....../‬هنــدي‬\n      ‫اجلنســية) يف قضيــة طالســم ســحرية بقصــد التــداوي وقــد تضمن القرار‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n      ‫قرارنــا رقــم ‪/33400432‬ج‪/2‬ب وتاريــخ ‪1433/9/3‬ه ـ قررنــا املصادقــة‬\n\n\n‫‪289‬‬\n\f‫علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/16‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪290‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":285,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3b977b06f44ae3b86b544df2a77e96a3d7a4f7e623844fd4d37b9e36fe2bdedb","normalized_text_hash":"ae890fd5f1001948755cb85b1f9359be74c8f5e72a13c816c59a6a5032643e09","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p285-33330091"},{"id":"4250ff50-2e3d-5ecf-aa92-cc6872fc0967","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -تلقي طر د يحتوي على أعمال سحرية -التعزير بالسجن واجللد وأخذ تعهد عليها.","document_number":"33436950","case_number":"33457292","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبوجب خطاب فضيلة رئيسها 296","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/24","year":"1434","subject":"سحر -تلقي طر د يحتوي على أعمال سحرية -التعزير بالسجن واجللد وأخذ تعهد عليها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33436950:‬تاريخه‪1433/10/24 :‬هـ‬\n                          ‫رقم الدعوى‪33457292:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 348796‬تاريخه‪1434/01/11:‬هـ‬\n\n\n       ‫ســحر ‪ -‬تلقــي طــر ٍد يحتــوي علــى أعمــالٍ ســحرية ‪ -‬التعزيــر بالســجن‬\n                                                   ‫واجللــد وأخــذ تعهــد عليهــا‪.‬‬\n\n\n\n\n       ‫‪ .1‬عــن عمــران بــن حصــن رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه‬\n       ‫وســلم رأى رجــا يف يــده حلقــة مــن صفــر فقــال ‪ :‬مــا هــذا ؟فقــال ‪ :‬مــن‬\n       ‫الواهنــة فقــال ‪ :‬انزعهــا فإنــه ال تزيــدك إال وهنــا فإنــك لومــت وهــي‬\n                                       ‫عليــك مــا أفلحــت أبــد ًا‪ .‬رواه اإلمــام أحمــد‬\n       ‫‪ .2‬عــن عقبــة بــن عامــر رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم‬\n       ‫قــال ( مــن تعلــق متيمــة فــا أمت اهلل لــه ومــن تعلــق ودعــه فــا ودع اهلل‬\n                       ‫لــه ) ويف روايــة ألحمــد ( مــن تعلــق متيمــة فقــد أشــرك )‬\n       ‫‪ .3‬عــن ابــن مســعود رضــي اهلل عنــه قــال ســمعت النبــي صلــى اهلل عليــه‬\n       ‫وســلم يقــول ( إن الرقــى والتمائــم والتولــة شــرك ) رواه أحمــد وأبــو داود‬\n       ‫‪ .4‬قولــه صلــى اهلل عليــه وســلم ( ليــس منــا مــن تطيــر أو تطيــر لــه أو‬\n                                        ‫تكهــن أو تكهــن لــه أو ســحر أو ســحر لــه ) ‪.‬‬\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليهــا بتلقــي طــرد يحــوي أعمــا ًال‬\n       ‫ســحرية لغــرض ســيء‪ ،‬وذلــك بعدمــا مت القبــض علــى املدعــى عليهــا‬\n\n‫‪291‬‬\n\f‫إثــر تلقيهــا لطــرد بريــدي بــه طالســم ســحرية عــن طريــق بريــد شــقيقها‬\n‫‪،‬وطلــب املدعــي العــام احلكــم عليهــا بعقوبــة تعزيريــة ‪،‬وبعــرض دعــوى‬\n‫املدعــي العــام علــى وكيــل املدعــى عليهــا صــادق علــى تلقــي الطــرد‬\n‫املذكــور ودفــع بــأن موكلتــه مريضــة نفســي ًا وشــاهدت يف إحــدى‬\n‫القنــوات راقي ـ ًا فطلبــت رقيــة شــرعية ف ُأرســل لهــا الطــرد املذكــور وال‬\n‫تعلــم عــن مــا يحتويــه وأنكــر اتهــام موكلتــه بــأن غرضهــا ســيء وإمنــا‬\n‫ـرت بدعــوى املدعــي‬  ‫الغــرض هــو العــاج ‪،‬ونظــر ًا ألن املدعــى عليهــا أقـ ْ‬\n‫العــام وأ َّنهــا تلقــت طــرد ًا يحتــوي علــى أعمــالٍ ســحرية وأنكــرت أن‬\n‫يكــون غرضهــا مــن ذلــك ســيئ ًا وإمنــا قصدهــا العــاج ومبــا أن مــا صــدر‬\n‫منهــا مــن احملــرم شــرع ًا بــل قــد يصــل إلــى الشــرك‪ ،‬لــذا كلــه ‪،‬وبنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيرهــا بســجنها ملــدة ثالثــة أشــهر‬\n‫وجلدهــا مائــة جلــدة مفرقــة علــى دفعتــن وأخــذ التعهــد بعــدم العــودة‬\n‫ملثــل مــا صــدر منهــا ‪،‬وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه وكالــة قناعتــه بــه وطلــب املدعــي العــام االســتئناف دون الئحــة‬\n‫اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى ‪،‬وبعــد رفــع احلكــم‬\n                                  ‫حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة باألحســاء مبوجــب خطــاب فضيلــة‬\n‫ـاء‬\n‫رئيــس احملكمــة اجلزئيــة رقــم‪33/614573‬يف ‪1433/04/03‬ه ـ بنـ ً‬\n‫علــى املعاملــة الــواردة إلينــا مــن مؤسســة رعايــة الفتيــات مبحافظــة‬\n‫األحســاء برقــم ‪2/192‬وتاريخ‪1433/07/09‬ه ـ واملقيــدة بهــذه‬\n\n                                                                                    ‫‪292‬‬\n\f      ‫احملكمــة برقم‪331297119‬وتاريخ‪1433/07/12‬ه ـ واحملالــة إلينــا‬\n      ‫مــن فضيلــة الرئيــس برقم‪33457292‬وتاريخ‪1433/07/12‬ه ـ ويف يــوم‬\n      ‫الثالثاء‪1433/07/22‬ه ـ افتتحــت اجللســة األولــى الســاعة احلادية عشــرة‬\n      ‫والنصــف وفيهــا حضــر املدعــي العــام ‪ ...‬امل َُع ّمــد بالترافــع أمــام احملكمــة‬\n      ‫طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام‬\n      ‫مبحافظــة األحســاء ذي الرقــم ه ـ ق‪ 137/2/2‬والتاريــخ ‪1431/1/5‬ه ـ‬\n      ‫ا ‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام‬       ‫وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫باألحســاء أدعــي علــى املــرأة‪24 ، ... /‬عامـاً‪ ،‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )...‬مفــرج عنهــا بالكفالــة اســتناد ًا للمــادة (‪)112‬‬\n                                                           ‫مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫إنــه بتاريــخ ‪32/1/29‬ه ـ قبــض علــى شــقيق املدعــى عليهــا املواطــن‪/‬‬\n      ‫‪......‬مــن قبــل مباحــث املنطقــة الشــرقية اثــر العثــور علــى طــرد بريــدي‬\n      ‫مــن مصــر إلــى العنــوان البريــدي اخلــاص بشــقيقها املواطن‪.../‬بداخلــه‬\n      ‫عــدد (‪ )4‬أربعــة أظــرف بهــا أوراق بلــغ عددهــا (‪ )75‬خمســة وســبعني‬\n      ‫قصاصــة حتتــوي علــى طالســم وأعمــال ســحرية احتــوت يف مجملهــا‬\n      ‫علــى االســتغاثة بالشــياطني مــن دون اهلل واالســتهانة باآليــات القرآنيــة‬\n      ‫وبأســماء اهلل احلســنى بطلــب وضعهــا يف أماكــن غيــر الئقــة مــن اجلســد‬\n      ‫أو طلــب حرقهــا وتبخيرهــا ونحــو ذلــك كمــا هــو موضــح يف طريقــة‬\n      ‫اســتخدامها يف عــدد (‪ )24‬أربــع وعشــرين قصاصــة مــن مجمــوع األوراق‪.‬‬\n      ‫وبضبــط إفــادة شــقيقها‪ /‬أفــاد أن شــقيقته املدعــى عليهــا هــي مــن طلبــت‬\n      ‫مــا تضمنــه الطــرد الــوارد علــى عنوانــه البريــدي كونهــا تعانــي مــن مــس‬\n      ‫شــيطاني وال يعــرف مــن املرســل لهــا ذلــك الطــرد (حفــظ االتهــام بحقــه‬\n      ‫لعــدم كفايــة األدلة)‪.‬وباســتجوابها أقــرت بأنهــا اتصلــت بشــخص يف‬\n\n\n‫‪293‬‬\n\f‫مصــر قبــل شــهر مــن القبــض عليهــا وطلبــت منــه طــرد لعالجهــا مــن مــا‬\n‫تعانيــه مــن خــوف ووســواس مبقابــل مبلــغ مالــي قــدره (‪ )1000‬ريــال‪،‬‬\n‫وطلــب منهــا أســماء شــقيقاتها وأزواجهــم ووالدتهــا‪ ،‬واتضــح أنــه يحتــوي‬\n‫علــى أعمــال ســحرية‪ ،‬وال علــم لشــقيقها مبــا يحتويــه الطرد‪.‬وقــد أســفر‬\n‫التحقيــق عــن اتهامهــا بتلقــي طــرد يحــوي أعمــا ًال ســحرية لغــرض‬\n‫ســيء‪ ،‬وفقـ ًا لقــرار االتهــام قــرار اتهــام رقــم (‪446‬ه ـ ق‪ )1205022‬لعــام‬\n                                  ‫‪1433‬ه ــ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪-1‬مــا ورد يف أقوالهــا املدونــة علــى ص (‪ ) 4-3‬مــن دفتــر التحقيــق املرفــق‬\n                                                                        ‫لفه (‪.)10‬‬\n                          ‫‪-2‬ما ورد يف محضر القبض املرفق لفه رقم (‪.)2‬‬\n‫‪-3‬مــا ورد يف أقــوال شــقيقها‪...‬املدونة علــى ص (‪ )2-1‬مــن دفتر التحقيق‬\n                                                                 ‫املرفــق لفه (‪.)10‬‬\n‫وباالطــاع علــى ســوابقها تبــن عــدم وجــود ســوابق مســجلة عليهــا‪.‬‬\n‫وحيــث إن مــا أقدمــت عليــه املدعــى عليهــا فعــل محــرم ومعاقــب عليــه‬\n‫شــرعاً‪ ،‬أطلــب إثبــات مــا أســند إليهــا واحلكــم عليهــا بعقوبــة تعزيريــة‬\n‫زاجــرة لهــا رادعــة لغيرهــا لقــاء مــا أســند إليهــا‪ .‬وبــاهلل التوفيــق هكــذا‬\n‫ا َّدعــى ؛ عليــه فقــد حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي‪...‬‬\n‫الوكيــل عــن املدعــى عليهــا ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة باألحســاء برقم‪33185813‬وتاريخ‪1433/07/21‬ه ـ ولــه‬\n‫فيهــا حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار وجــرى تــاوة دعــوى‬\n‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهــام‬‫املدعــي العــام عليــه فأجــاب قائـ ً‬\n‫موكلتــي بتلقــي طــرد يحتــوي علــى أعمــالٍ ســحرية صحيــح والــذي‬\n‫حصــل أن موكلتــي مريضــة نفســي ًا وشــاهدت يف إحــدى القنــوات شــيخ ًا‬\n\n\n                                                                                       ‫‪294‬‬\n\f      ‫مصري ـ ًا يرقــي النــاس فطلبـ ْـت منــه رقيــة شــرعية عــن طريــق الهاتــف‬\n      ‫وحولــت لــه املبلــغ املذكــور وأرســل الطــرد املذكــور وال نعلــم عــن‬\n      ‫مــا يحتويــه وموكلتــي متعلمــة إلــى املرحلــة املتوســطة واملــرض جعلهــا‬\n      ‫تطلــب هــذا الطلــب وأمــا مــا ذكــره املدعــي العــام مــن اتهــام موكلتــي‬\n      ‫ـيء فغيــر صحيــح فالغــرض هــو عالجهــا كمــا‬            ‫أن غرضهــا مــن ذلــك سـ ٌ‬   ‫َّ‬\n      ‫ذكــرت هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام هــل لديــه بينــة‬\n      ‫علــى دعــواه فقــال نعــم وهــي موجــودة يف أوراق املعاملــة وأطلــب الرجــوع‬\n      ‫إليهــا هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة فلــم‬\n      ‫أن غرضهــا مــن تلقــي طــرد يحتــوي‬       ‫أجــد فيهــا مايديــن املدعــى عليهــا مــن َّ‬\n      ‫ـيء ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‬      ‫علــى أعمــالٍ ســحرية سـ ٌ‬\n      ‫ومنهــا كــرت ســوابق املدعــى عليهــا املتضمــن عــدم وجــود ســوابق عليهــا‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬    ‫فبنـ ً‬\n      ‫عليهــا والتأكــد مــن أهليتهــا وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا‬\n      ‫ـرت بدعــوى املدعــي العــام وأ َّنهــا تلقــت طــرد ًا يحتــوي‬‫أن املدعــى عليهــا أقـ ْ‬\n      ‫علــى أعمــالٍ ســحرية وأنكــرت أن يكــون غرضهــا مــن ذلــك ســيئ ًا وإمنــا‬\n      ‫قصدهــا العــاج ومبــا أن ماصــدر منهــا مــن احملــرم شــرع ًا بــل قــد يصــل‬\n      ‫إلــى الشــرك فقــد روى اإلمــام أحمــد عــن عمــران بــن حصــن رضــي اهلل‬\n      ‫عنــه أن النبــي صلــى اهلل عليــه وســلم رأى رجــا يف يــده حلقــة مــن صفــر‬\n      ‫فقــال ‪ :‬مــا هــذا ؟فقــال ‪ :‬مــن الواهنــة فقــال ‪ :‬انزعهــا فإنــه التزيــدك إال‬\n      ‫وهنــا فإنــك لومــت وهــي عليــك مــا أفلحــت أبــد ًا وروى عــن عقبــة بــن‬\n      ‫عامــر رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم ( مــن تعلــق متيمــة‬\n      ‫فــا أمت اهلل لــه ومــن تعلــق ودعــه فــا ودع اهلل لــه ) ويف روايــة ألحمــد‬\n      ‫(مــن تعلــق متيمــة فقــد أشــرك ) وروى أحمــد وأبــو داود عــن ابــن مســعود‬\n\n\n‫‪295‬‬\n\f‫رضــي اهلل عنــه قــال ســمعت النبــي صلــى اهلل عليــه وســلم يقــول ( إن‬\n‫الرقــى والتمائــم والتولــة شــرك ) وقــال صلــى اهلل عليــه وســلم ( ليــس منــا‬\n‫مــن تطيــر أو تطيــر لــه أو تكهــن أو تكهــن لــه أو ســحر أو ســحر لــه )‬\n‫وهــذه األدلــة تــدل علــى عظــم مــا أقدمــت عليــه املدعــى عليهــا ملــا يف ذلــك‬\n‫مــن القــدح يف التوحيــد والتعلــق بغيــر اهلل والتــوكل علــى غيــره ممــا‬\n‫يســتلزم تعزيــر املدعــى عليهــا علــى ذلــك لــذا كلــه وألجــل احلــق العــام‬\n‫حكمــت علــى املدعــى عليهــا مبــا يلــي ‪ :‬أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى‬\n‫عليهــا بتلقــي طــر ٍد يحتــوي علــى أعمــالٍ ســحرية ألجــل العــاج وعزرتهــا‬\n‫ألجــل ذلــك بســجنها ملــدة ثالثــة أشــهر حتتســب منهــا املــدة التــي أوقــف‬\n‫فيهــا علــى ذمــة القضيــة وبجلدهــا مائــة جلــدة مفرقــة علــى دفعتــن كل‬\n‫دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة‬\n‫ـدي أن تلقيهــا لهــذا الطــرد لغــرض ســيء وقــررت‬      ‫أيــام ‪ .‬ثانيـ ًا ‪ /‬لــم يثبــت لـ َّ‬\n‫رد دعــوى املدعــي العــام بإثبــات ذلــك ‪ .‬ثالثـ ًا ‪ /‬يؤخــذ عليهــا التعهــد بعــدم‬\n‫العــودة ملثــل ماصــدر منهــا وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعى‬\n‫عليــه وكالــة بحــق موكلتــه يف متييــز احلكــم قــرر قناعتــه بــه وطلــب‬\n‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم دون الئحــة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‬\n‫وأقفلــت اجللســة الســاعة التاســعة والنصــف وصلــى اهلل وسـلَّم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/10/24‬ه ـ‬\n‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫ويف يــوم األربعاء‪1433/12/22‬ه ـ فتحــت اجللســة الثالثــة الســاعة‬\n‫التاســعة والنصــف وفيهــا حضــر الطرفــان وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف مبوجــب خطــاب فضيلــة رئيســها‬\n\n\n                                                                                                 ‫‪296‬‬\n\f      ‫رقم‪331990313‬وتاريخ‪1433/11/23‬ه ـ وبرفقهــا قــرار الدائــرة‬\n      ‫اجلزائيــة الثالثيــة الثانيــة رقم‪33453226‬وتاريخ‪1433/11/14‬ه ـ‬\n      ‫املتضمــن مانصــه ‪ »:‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫لوحــظ أن مــا ذكــره فضيلتــه يف ثانيــا ممــا حكــم بــه ال وجــه لــه حيــث‬\n      ‫إن مــا تلقتــه املدعــى عليهــا مــن أعمــال ســحرية يعتبر ســيئ ًا فعلى فضيلته‬\n      ‫مالحظــة مــا ذكــر إليــه وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة واهلل‬\n      ‫ـأن التلقــي كان‬   ‫املوفــق» ا‪.‬ه ـ عليــه أجيــب مشــايخي نفــع اهلل بعلمهــم بـ َّ‬\n      ‫ســيئ ًا لكـ َّـن غرضهــا لــم يكــن منــه إيــذاء غيرهــا وإمنــا كان لقصــد‬\n      ‫عالجهــا وهــو مــا يتضــح مــن حالهــا إذ هــي مريضــة وجاهلــة كمــا حصــل‬\n      ‫مــن نقاشــها يف إحــدى اجللســات واخلــاف يف مســألة هــل كان غرضهــا‬\n      ‫ـيء وعليــه فلــم‬\n                      ‫منــه ســيئ ًا وليــس يف كــون تلقيهــا لهــذا العمــل أنــه سـ ٌ‬\n      ‫ـرت بالتهميــش علــى قــرار‬    ‫يظهــر لــي ســوى ماحكمــت بــه ســابق ًا وأمـ ُ‬\n      ‫احلكــم مبــا طــرأ عليــه ومــن ثـ ّـم إعــادة املعاملــة حملكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية لتدقيــق احلكــم وأقفلــت اجللســة الســاعة العاشــرة‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ُحـ ِـر َر‬\n      ‫يف‪1433/12/22‬ه ـ احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n      ‫الدائ ــرة اجلـزائي ــة الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫علــى املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/32481‬ج‪ 2‬وتاريــخ‬\n      ‫‪1434/1/5‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n      ‫األحســاء برقــم ‪ 33/2217726‬وتاريــخ ‪1433/12/28‬ه ـ املرفــق بهــا‬\n      ‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشيخ‪....../‬املســجل‬\n      ‫برقــم ‪ 33436950‬وتاريــخ ‪1433/10/24‬ه ـ اخلــاص بدعوى‪/‬املدعــي‬\n      ‫العــام ضــد‪.../‬يف قضيــة ســحر وقــد تضمــن القــرار حكــم فضيلتــه مبــا‬\n\n\n‫‪297‬‬\n\f‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القرار وصورة ضبطــه وأوراق املعاملة‬\n‫وباإلطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا رقــم ‪/33453226‬‬\n‫ج‪/2‬ب وتاريــخ ‪1433/11/14‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد‬\n‫اإليضــاح األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                               ‫وصحبــه وســلم‪ .‬حــرر يف‪1434/1/11‬هــ‪.‬‬\n\n\n\n\n                                                                             ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":291,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5041ef93827f68434dac9ae1e7b7b03d78a9c85f6bf8285ab907a6f6030b4f6f","normalized_text_hash":"c26451ca638c86f26caf2657b64e6fa2b2d9a3aead4c8477e42e3430aa6a7029","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p291-33436950"},{"id":"0e7791ca-1dee-518c-8ff0-6fa709f3fd96","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -ممارسة أعمال الشعوذة والدجل -اإلضرار بالغير - اختصاص المحكمة العامة.","document_number":"3454811","case_number":"33661865","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/03","year":"1434","subject":"سحر -ممارسة أعمال الشعوذة والدجل -اإلضرار بالغير - اختصاص المحكمة العامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3454811:‬تاريخه‪1434/03/03 :‬هـ‬\n                         ‫رقم الدعوى‪33661865:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34357255‬تاريخه‪1434/11/11:‬هـ‬\n\n\n      ‫ســحر‪ -‬ممارســة أعمــال الشــعوذة والدجــل ‪ -‬اإلضــرار بالغيــر ‪-‬‬\n                                         ‫اختصــاص احملكمــة العامــة‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬حد الساحر القتل ‪.‬‬\n                                  ‫‪ -2‬املادة (‪ )135‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهــا مبمارســة أعمــال الشــعوذة‬\n      ‫والدجــل بقصــد اإلضــرار بالغيــر‪ ،‬وذلــك بعدمــا مت القبــض عليهــا مــن‬\n      ‫قبــل اجلهــات املختصــة‪ ،‬إثــر شــكوى مــن كفيلهــا مفــاده قيامهــا بعمــل‬\n      ‫ســحر لوالدتــه‪ ،‬وطلــب املدعــي العــام احلكــم عليهــا بعقوبــة تعزيريــة‪،‬‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهــا عــن طريــق املترجــم‬\n      ‫صادقــت علــى الدعــوى وقــررت أن ســحرها كان لكبــار العائلــة‬\n      ‫التــي تعمــل لديهــم دون صغارهــم ‪،‬ولكــون املدعــى عليــه اعترفــت‬\n      ‫بالســحر‪ ،‬وألن حــد الســاحر ضربــة بالســيف‪ ،‬ولكــون ذلــك مــن‬\n      ‫اختصــاص احملكمــة العامــة ‪،‬فقــد مت احلكــم بصــرف النظــر عــن‬\n      ‫دعــوى املدعــي العــام لعــدم االختصــاص ‪،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليهــا قــررت القناعة‪،‬وقــرر املدعــي العــام االعتــراض مكتفيــا بالئحــة‬\n\n‫‪303‬‬\n\f‫الدعوى‪،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33661865‬وتاريــخ ‪1433/11/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332051477‬وتاريــخ ‪1433/11/17‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق ‪1434/03/02‬ه ـ افتتحــت اجللســة الســاعة ‪07 : 30‬‬\n‫وفيهــا قــدم املدعــي العــام الئحــة دعــوى عامــة ضــد ‪...‬أندونيســية اجلنســية‬\n‫حتمــل رخصــة إقامــة رقــم ‪...‬جــاء فيهــا بتاريــخ ‪1433/10/24‬ه ـ مت‬\n‫القبــض علــى املذكــورة مــن قبــل الشــرطة العســكرية باحلــرس الوطنــي‬\n‫لشــكوى مــن كفيلهــا ‪ ،...‬ســعودي اجلنســية مــن أن عاملتــه املنزليــة‬\n‫املذكــورة قامــت بعمــل ســحر لوالدتــه وخلطتــه مــع «احلنــاء والعويــدي»‬\n‫ووضعتــه علــى رأســها وأصبحــت تشــتكي والدتهــا مــن الــم برأســها‬\n‫واحمــرار عينيهــا وحكــة بيديهــا وعنــد ســؤاله للمذكــورة أفــادت‬\n‫بأنهــا عملــت الســحر لهــا بســبب غضبهــا مــن األوالد ‪ ،‬وذكــرت بأنهــا‬\n‫تســتطيع فكــه وقامــت بالقــراءة بــكاس بــه مــاء وقــام هــو بغســل رأس‬\n‫أمــه ويديهــا وغســلها مبــاء فيهــا رقيــة وشــفيت‪ -‬جــرى االتصــال باملدعــي‬\n‫وأفــاد بأنــه ليــس لديــة بينــه علــى قيــام املذكــورة باإلضــرار بوالدتــه إال‬\n                                                                        ‫أقرارهــا‪.‬‬\n     ‫‪ -‬جرى إيقافها استناد ًا للمادة (‪ )112‬من نظام اإلجراءات اجلزائية‪.‬‬\n‫وبســماع أقوالهــا واســتجوابها أفــادت بأنهــا تقــوم بأعمــال الســحر‬\n‫وحتضــر اجلــان وأنهــا قامــت بســحر والــده كفيلهــا بســبب إســاءة أوالد‬\n\n                                                                                      ‫‪304‬‬\n\f      ‫كفيلهــا لهــا وانــه أرادت ســحر األوالد إال أنهــا بعــد حتضيرهــا للجــان‬\n      ‫طلــب منهــا تــرك األوالد لصغــر ســنهم وطلــب منهــا القيــام بســحر والــدة‬\n      ‫كفيلهــا كمــا انــه طلــب منهــا أن تضعــه بخلطة « احلنــا والعويدي»‪ ،‬وقد‬\n      ‫تعلمــت الســحر منــذ أن كان عمرهــا (‪ )10‬عشــر ســنوات ببلدهــا وهــي‬\n      ‫تعلــم بحرمتــه‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن اتهــام املذكــورة‬\n                   ‫مبمارســة أعمــال الشــعوذة والدجــل بقصــد اإلضــرار بالغيــر‪.‬‬\n                                                      ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬ماجــاء بأقوالهــا املدونــة مبحضــر االســتدالل لفــة (‪ )1‬ومحضــري‬\n                                                            ‫االســتجواب لفــة(‪.)14,2‬‬\n      ‫‪ -2‬مــا تضمنــه محضــر القبــض املعــد مــن قبــل جهــاز اإلرشــاد والتوجيــه‬\n      ‫برئاســة احلــرس الوطنــي املرفــق لفــة (‪)4‬وحيــث أن مــا أقدمــت عليــه‬\n      ‫املذكــورة فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا أســند‬\n                                           ‫إليهــا واحلكــم عليهــا بعقوبــة تعزيريــة‪.‬‬\n      ‫وبــاهلل التوفيــق هــذه دعــواي هــذا و باالطــاع علــى أوراق املعاملــة‬\n      ‫ألفيــت إقــرار املدعــى عليهــا علــى صفحــة (‪ )3‬لفــة (‪ )14‬بعملهــا الســحر‬\n      ‫و أنهــا تعلــم حرمتــه و ألن حــد الســاحر القتــل و ألن النظــر يف ذلــك‬\n      ‫مــن اختصــاص احملكمــة العامــة و ملــا جــاء يف املــادة (‪ )135‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة فقــد قــررت عــدم االختصــاص بنظــر هــذه القضيــة‬\n      ‫و ســوف ترفــع املعاملــة حملكمــة االســتئناف حســب املتبــع و صلــى اهلل‬\n      ‫و ســلم علــى نبينــا محمــد و علــى آلــه و صحبــه حــرر يف ‪1434/3/2‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د ‪... .‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33661865‬وتاريــخ ‪ 1433/11/17‬ه ـ املقيــدة‬\n\n\n‫‪305‬‬\n\f‫باحملكمــة برقــم ‪ 332051477‬وتاريــخ ‪ 1433/11/17‬ه ـ ففــي يــوم‬\n‫الثالثاء املوافق‪ 1434/08/23‬هـ افتتحت اجللسة وفيها حضرت املدعى‬\n‫عليها ‪ (...‬اندونيسية اجلنسية ) حتمل رخصة إقامة رقم (‪ )...‬وقد وردتنا‬\n‫املعاملــة مــن محكمــة االســتئناف بقــرار املالحظــة رقــم ‪ 34219104‬يف‬\n‫‪1434/5/21‬ه ـ واملتضمــن بعــد املقدمــة أنــه بدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة لوحــظ أن احلكــم بصــرف النظــر عــن الدعــوى‬\n‫لعــدم االختصــاص قبــل إحضــار املدعــى عليهــا وســماع إجابتهــا علــى‬\n‫الدعــوى ســابق ألوانــه الســيما وأن اعترافهــا الــذي اســتند إليــه فضيلتــه‬\n‫غيــر مصــدق شــرع ًا كمــا أن املدعــي العــام يطالــب بتعزيزهــا لقــاء مــا‬\n‫نســب إليهــا فعلــى فضيلتــه إحضــار املدعــى عليهــا وعرض دعــوى املدعي‬\n‫العــام عليهــا فــإذا أجابــت وأعترفــت مبــا يوجــب احلــد يصــار إلــى صــرف‬\n‫النظــر لعــدم االختصــاص وإال عزرهــا فضيلتــه مبــا يظهــر فعلــى فضيلتــه‬\n‫مالحظــة مــا ذكــر وإجــراء مــا يلــزم نحوهــا وإحلــاق مخلــص مــا يجريــه‬\n‫يف الضبــط إلــى القــرار ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا حســب‬\n‫التعليمــات وجواب ـ ًا عليــه فقــد جــرى عــرض الدعــوى العامــة املقدمــة‬\n‫مــن املدعــي العــام ‪...‬علــى املدعــى عليهــا عــن طريــق مترجــم احملكمــة‬\n‫‪...‬وصادقــت علــى الدعــوى جملــة وتفصيــا إال أنهــا قالــت إن ســحرها‬\n‫كان لكبــار العائلــة التــي تعمــل لديهــم دون صغارهــم هكــذا أجابــت‬\n‫وألن املدعــى عليهــا اعترفــت بعمــل الســحر وألن حــد الســاحر ضربــة‬\n‫بالســيف وألن نظــر هــذه القضايــا مــن اختصــاص احملكمــة العامــة فــإن‬\n‫لــم يظهــر لــي خــاف مــا قــررت ســلف ًا وبعرضــه عليهمــا قــررت املدعــى‬\n‫عليهــا القناعــة واملدعــي العــام االعتــراض مكتفي ـ ًا بالئحــة الدعــوى‬\n‫وكان النطــق باحلكــم يف ‪ 1434/8/23‬ه ـ وأغلقــت اجللســة الســاعة‬\n\n\n                                                                                  ‫‪306‬‬\n\f      ‫العاشــرة والنصــف وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن‬\n      ‫قضــاة الدائــرة اجلزائيــة الرابعــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n      ‫‪ 341367329‬وتاريــخ ‪ 1434/10/8‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ د‪ ... .‬املســجل برقــم ‪3454811‬‬\n      ‫وتاريــخ ‪1434/3/3‬ه ـ املتعلقــة بدعــوى املدعــي ضــد ‪ .......‬أندونيســية‬\n      ‫اجلنســية (‪ )...‬التهامهــا يف قضيــة أعمــال الســحر و الشــعوذة والدجــل‬\n      ‫بقصــد اإلضــرار بالغيــر املتضمــن حكــم فضيلتــه مبــا هــو مــدون بــه‬\n      ‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم ‪ 34219104‬وتاريــخ ‪1434/5/21‬ه ـ قــررت الدائــرة‬\n      ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق و صلــى اهلل‬\n                                          ‫علــى نبينــا محمــد و آلــه وصحبــه وســلم‪0‬‬\n\n\n\n\n‫‪307‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":303,"source_page_end":307,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83eac654a0d728513c56434ddf9faf516aaa15e7c393efeddd0977b76fcb6559","normalized_text_hash":"fcceae2e3b31b80ea10b74b8137e278cf72afd6b91cf5d9ef465b30768608688","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p303-3454811"},{"id":"3d8199e8-d15a-5282-84e0-4b0b300ca770","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -حيازة طالسم سحرية -الدفع باجلهل -ثبوت اإلدانة باإلقرار -التعزير بالسجن واجللد وأخذ التعهد.","document_number":"34192532","case_number":"34113973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/20","year":"1434","subject":"سحر -حيازة طالسم سحرية -الدفع باجلهل -ثبوت اإلدانة باإلقرار -التعزير بالسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34192532:‬تاريخه‪1434/04/20 :‬هـ‬\n                    ‫رقم الدعوى‪34113973:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34256249‬تاريخه‪1434/07/01 :‬هـ‬\n\n\n ‫ســحر ‪ -‬حيــازة طالســم ســحرية ‪ -‬الدفــع باجلهــل ‪ -‬ثبــوت اإلدانــة‬\n                 ‫باإلقــرار ‪ -‬التعزيــر بالســجن واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم ‪ « :‬مــن تعلــق متيمــة فــا أمت اهلل‬\n                                                                               ‫لــه»‬\n ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم ملــا رأى متيمــة علــى رجــل « انزعهــا فإنها‬\n       ‫ال تزيــدك إال وهنــا فإنــك لــو مــت وهــي عليــك مــا أفلحــت أبدا»‪.‬‬\n                              ‫‪ -3‬قاعدة ‪ :‬اإلقرار حجة شرعية على املقر‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليه بحيازته طالســم ســحرية محرمة‬\n ‫شــرعا وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪،‬‬\n ‫حيــث قبــض علــى املدعــى عليــه علــى إثــر االشــتباه بــه وعثــر بحوزتــه‬\n ‫علــى قصاصــة ورقيــة يشــتبه بــأن تكــون طالســم ســحرية وبعرضهــا‬\n ‫علــى أحــد املختصــن بقضايــا الســحر بهيئــة األمــر باملعــروف والنهــي‬\n ‫عــن املنكــر تبــن أنهــا قصاصــة حتتــوي علــى طالســم ســحرية وامتهــان‬\n ‫لــكالم اهلل تعالــى وتقطيــع حروفــه والعبــث بــه ‪،‬وأقــر املدعــى عليــه‬\n ‫بحيــازة الورقــة املشــار إليهــا يف الدعــوى ودفــع بأنــه حصــل عليهــا مــن‬\n\n                                                                                       ‫‪308‬‬\n\f      ‫شــيخ باملدينــة املنــورة لكــي تلــد زوجتــه وأنــه يجهــل كونهــا طالســم‬\n      ‫ســحرية ‪،‬وبنــاء علــى إقــرار املدعــى عليــه ولعــدم قبــول مــا دفــع بــه مــن‬\n      ‫جهــل وألن الواجــب علــى املســلم أن يعــرف احلكــم الشــرعي قبــل أن‬\n      ‫يقــدم عليــه ‪ ،‬وألن تعليــق التميمــة والطالســم الســحرية محــرم شــرعا‬\n      ‫‪،‬فقــد حكمــت احملكمــة بســجنه شــهرا مــن تاريــخ إيقافــه وجلــده‬\n      ‫أربعــن جلــدة وأخــذ التعهــد عليــه بعــدم تكــرار ذلــك ‪،‬وقــرر املدعــى‬\n      ‫‪،‬وصــدق‬\n           ‫عليــه القناعــة باحلكــم بينمــا اعتــرض املدعــي العــام بالئحــة ُ‬\n                                                 ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                                  ‫ّ‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 34113973‬وتاريــخ‬\n      ‫‪1434/03/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34599849‬وتاريــخ‬\n      ‫‪1434/03/09‬ه ـ حضــر املدعــي العــام ‪...........‬وادعــى ضــد ‪...........‬مينــي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة (‪ )...........‬قائــا يف حتريــر دعــواه‬\n      ‫حيــث إنــه بتاريــخ ‪1433/9/20‬ه ـ ورد للشــرطة تقريــر دوريــة األمــن رقم‬\n      ‫(‪ )...........‬املتضمــن القبــض علــى املدعــى عليــه رفــق ابنــه بشــارع ‪...........‬‬\n      ‫بالهفــوف لالشــتباه بهمــا وقــد عثــر بحوزتــه علــى قصاصــة ورقيــة يشــتبه‬\n      ‫أن تكــون طالســم وبعــرض الطالســم علــى املختصــن بقضايــا الســحر‬\n      ‫بهيئــة األمــر باملعــروف والنهــى عــن املنكــر تبــن أنهــا قصاصــة حتتــوي‬\n      ‫علــى طالســم ســحرية وامتهــان كالم اهلل وتقطيــع حروفــه والعبــث‬\n      ‫بــه واالســتعانة بالشــياطني واجلــن و باســتجوابه أقــر بحيازتــه لتلــك‬\n\n‫‪309‬‬\n\f‫الورقــة وأنــه حصــل عليهــا مــن شــيخ باملدينــة املنــورة لكــي تلــد زوجتــه‬\n‫وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام بحيــازة طالســم ســحرية‬\n‫محرمــه شــرع ًا وذلــك لألدلــة والقرائــن التاليــة ‪-1‬إقــرار مبــا نــوه عنــه‬\n‫املــدون بالصفحــة رقــم (‪ )13،12‬مــن ملــف التحقيــق املرفــق لفــه (‪)1‬‬\n‫‪ -2‬تقريــر دوريــه األمــن املتضمــن القبــض عليــه يف حالــة اشــتباه بطريــق‬\n‫‪...........‬املرفــق لفــه (‪-3 )2‬تقريــر رئيــس مركــز هيئــة األمــر باملعــروف‬\n‫املرفــق لفــه (‪ -4 )19‬القصاصــة املــدون عليهــا طالســم املرفقــة لفــة (‪)18‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة رادعــة لــه وزاجــره لغيــره وفقــا للوجــه‬\n‫الشــرعي وبعــرض تلــك الدعــوى علــى املدعــى عليــه أجــاب قائــا أصــادق‬\n‫علــى مــا ذكــره املدعــي العــام مــن حيازتــي لورقــة مكتــوب فيهــا آيــات‬\n‫قرآنيــة وأدعيــة وبعــض أســماء اهلل احلســنى والســبب يف حملــي لتلــك‬\n‫الورقــة حيــث إننــي لــم يرزقنــي اهلل إال بولــد واحــد وعمــره اآلن ثمانيــة‬\n‫عشــرة عامـ ًا وقــد ذكــر لــي عــن أحــد األشــخاص أنــه يعالــج مثــل حالتــي‬\n‫فذهبــت إليــه وأعطانــي ورقــة وقــال لــي اجعلهــا دائمــا معــك وســوف‬\n‫يرزقــك اهلل أوالدا وال اعلــم إن كانــت تلــك الورقــة هــي طلســم ســحري‬\n‫وأضــاف قائــا إننــي اعمــل باململكــة منــذ خمــس وثالثــن ســنه و لــذا‬\n‫وبعــد ســماع الدعــوى واإلجابــة وتصفــح أوراق املعاملــة وحيــث طلــب‬\n‫املدعــي العــام إثبــات إدانــة املدعــى عليــه حليازتــه طلســم ســحري حتتــوي‬\n‫باجلملــة علــى آيــات قرآنيــة وأدعيــة وبعــض أســماء اهلل احلســنى وأرقــام‬\n‫وكلمــات مبهمــة وحــروف مقطعــة ومجازاتــه لقــاء ذلــك وان املدعــى‬\n‫عليــه قــد أقــر بذلــك وان اإلقــرار حجــة شــرعية علــى املقــر وإن مــا تــذرع‬\n\n\n                                                                                     ‫‪310‬‬\n\f      ‫بــه املدعــى عليــه ال يعفيــه مــن املســؤولية الن الواجــب علــى اإلنســان أن‬\n      ‫يتأكــد عــن احلكــم الشــرعي ملــا يريــد فعلــه ال ســيما وإنــه يعيــش يف‬\n      ‫هــذا البــاد املباركــة وإنــه قــد ثبــت بــأن مــا يحملــه معــه حتتــوي علــى‬\n      ‫طالســم ســحرية محرمــة شــرعا وإن مــا أقــدم عليــه املدعــى عليــه حــرام‬\n      ‫وإجــرام وحلرمــة تعليــق التمائــم والطالســم وملــا ورد مــن النهــي الشــديد‬\n      ‫يف ذلــك وإلثرهــا الســيء علــى عقيــدة مســتعملها ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم( مــن تعلــق متيمــة فــا أمت اهلل لــه (ولقــول النبــي صلــى اهلل عليــه‬\n      ‫ســلم ملــا رآهــا علــى رجــل فقــال (انزعهــا إنهــا ال تزيــدك إال وهن ـ ًا فإنــك‬\n      ‫لــو مــت وهــي عليــك مــا أفلحــت أبــداً( لــذا فقــد تقــرر مايلــي أوال ثبــوت‬\n      ‫ادانــة املدعــى عليــه ‪...........‬حليازتــه طلســم ســحري يحتــوي علــى آيــات‬\n      ‫قرآنيــة وأدعيــة وبعــض أســماء اهلل احلســنى وأرقــام وكلمــات مبهمــة‬\n      ‫وحــروف مقطعــة ومجازاتــه لقــاء ذلــك بســجنه شــهرا يبــدأ مــن تاريــخ‬\n      ‫ايقافــه بســبب هــذه القضيــة وجلــده أربعــن جلــده ثانيــا أخــذ التعهــد‬\n      ‫الــازم عليــه بعــدم تكــرار مــا بــدر منــه مــرة أخــرى وبذلــك كلــه‬\n      ‫حكمــت وبعرضــه اعتــرض عليــه املدعــي العــام وطلــب رفعــه حملكمــة‬\n      ‫االســتئناف مكتفيــا مبــا جــاء يف دعــواه عــن تقــدمي الئحــة اعتراضيــة‬\n      ‫كمــا قــرر املدعــى عليــه عــدم قناعتــه بــه وطلــب تقــدمي الئحــة اعتراضيــة‬\n      ‫عليــه فجــرى إفهامــه بــأن عليــه مراجعــة احملكمــة يــوم الثالثــاء املوافــق‬\n      ‫‪1434/4/30‬ه ـ الســتالم صــوره مــن القــرار الشــرعي وأن لــه مدة ثالثني‬\n      ‫يــوم تبــدأ مــن ذلــك التاريــخ بعدهــا يســقط حقــه يف تقــدمي الالئحــة وقــد‬\n      ‫فهــم ذلــك وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n‫‪311‬‬\n\f‫األولى مبحكمة االســتئناف باملنطقة الشــرقية على املعاملة الواردة من‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف ‪...........‬‬\n‫برقــم ‪ 34/687997‬وتاريــخ ‪1434/6/10‬ه ـ املقيــدة لــدى احملكمــة‬\n‫برقــم ‪ 34/1465163‬وتاريــخ ‪1434/6/18‬ه ـ املرفــق بهــا القرار الصادر‬\n‫مــن فضيلتــه املســجل برقــم ‪ 34192532‬وتاريــخ ‪1434/4/20‬ه ـ اخلــاص‬\n‫بدعوى‪/‬املدعــى العــام ضد‪....................../‬مينــي اجلنســية يف قضية ســحر‬\n‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                               ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/7/1‬ه ـ‬\n\n\n\n\n                                                                                   ‫‪312‬‬\n\f                        ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى وكيل إلحدى املؤسسات ضد مكفولها‬\n  ‫‪5‬‬                                                       ‫خيانة أمانة‬   ‫‪1‬‬\n           ‫خليانته األمانة بأخذه مبلغا ماليا أثناء عمله‬\n\n\n         ‫دعوى عامة ضد شخصني ألخذهما مبلغا مالي ًا‬\n  ‫‪10‬‬                                                      ‫خيانة أمانة‬   ‫‪2‬‬\n                    ‫من الشركة التي يعمالن فيها‬\n\n\n         ‫دعوى عامة ضد مندوب مبيعات شركة لقيامه‬\n  ‫‪18‬‬                                                      ‫خيانة أمانة‬   ‫‪3‬‬\n             ‫بالنصب واالحتيال املالي وخيانة األمانة‬\n\n\n            ‫دعوى عامة ضد شخص خليانته األمانة‬\n           ‫باالستيالء على ملفات ومستندات ملشاريع‬\n  ‫‪24‬‬                                                      ‫خيانة أمانة‬   ‫‪4‬‬\n          ‫املؤسسة وإخفائها بقصد اإلضرار واملساومة‬\n                          ‫على إرجاعها‬\n\n\n         ‫دعوى عامة ضد شخصني لقيامهما باختالس‬\n  ‫‪34‬‬     ‫مبلغ مالي كبير من مجموعة صرافات بنك‬              ‫خيانة أمانة‬   ‫‪5‬‬\n             ‫أثناء عملهما يف تغذية الصرافات‬\n\n\n            ‫دعوى عامة ضد شخص لقيامه بالنصب‬\n  ‫‪46‬‬      ‫واالحتيال عن طريق جمع أموال الناس وإيهام‬        ‫خيانة أمانة‬   ‫‪6‬‬\n              ‫أصحابها بتوظيفها مبكاسب وهمية‬\n\n\n          ‫دعوى عامة ضد شخصني خليانتهما األمانة‬\n  ‫‪54‬‬     ‫بأخذهما مبلغا ماليا من مدير الشركة وعدم‬          ‫خيانة أمانة‬   ‫‪7‬‬\n                    ‫توريده لشركة الصرافة‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬      ‫م‬\n\n\n         ‫دعوى عامة ضد ثالثة مقيمني خليانتهم األمانة‬\n  ‫‪66‬‬                                                  ‫خيانة أمانة‬   ‫‪8‬‬\n           ‫باستيالئهم على أغذية من إعاشة السجناء‬\n\n\n         ‫دعوى عامة ضد شخص لدخوله منزال دون إذن‬        ‫انتهاك حرمة‬\n  ‫‪77‬‬                                                                ‫‪9‬‬\n               ‫صاحبه ومقاومة الفرقة القابضة‬              ‫منزل‬\n\n\n         ‫دعوى عامة ضد شخص لقيامه بالقفز من سور‬\n                                                      ‫انتهاك حرمة‬\n  ‫‪83‬‬     ‫املنزل ومن ثم دخوله عبر فتحة مكيف إحدى‬                     ‫‪10‬‬\n                                                         ‫منزل‬\n                   ‫الغرف بغرض السرقة‬\n\n\n         ‫دعوى عامة ضد شخص لدخوله منزال لالطالع‬        ‫انتهاك حرمة‬\n  ‫‪90‬‬                                                                ‫‪11‬‬\n               ‫على أهله من خالل نوافذ املنزل‬             ‫منزل‬\n\n\n         ‫دعوى عامة ضد شخص لقيامه بدخول منزل‬\n                                                      ‫انتهاك حرمة‬\n  ‫‪99‬‬      ‫بغير إذن صاحبه وإقامة عالقة محرمة مع‬                      ‫‪12‬‬\n                                                         ‫منزل‬\n                         ‫خادمته‬\n\n\n          ‫دعوى عامة ضد شخص العتدائه على حدث‬\n ‫‪107‬‬                                                     ‫حرابة‬      ‫‪13‬‬\n                 ‫وفعل الفاحشة به بالقوة‬\n\n\n           ‫دعوى عامة ضد مقيم خلطفه طفال وفعل‬\n ‫‪116‬‬                                                     ‫حرابة‬      ‫‪14‬‬\n                       ‫الفاحشة به‬\n\n\n          ‫دعوى عامة ضد شخص خلطفه حدث ًا وفعل‬\n ‫‪126‬‬     ‫الفاحشة به ومحاولة خطف حدث آخر والهرب‬           ‫حرابة‬      ‫‪15‬‬\n             ‫من رجال األمن ‪ ،‬وصدم دورية أمنية‬\n\f‫الصفحة‬                     ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد شخص الستدراجه شابا ملنزله‬\n ‫‪156‬‬     ‫وفعل الفاحشة به بالقوة حتت تهديد السكني ‪،‬‬      ‫حرابة‬    ‫‪16‬‬\n                        ‫وشربه املسكر‬\n\n\n            ‫دعوى عامة ضد شخصني الشتراكهما يف‬\n          ‫ارتكاب جرمية قطع الطريق وإخافة السبيل ؛‬\n ‫‪176‬‬                                                    ‫حرابة‬    ‫‪17‬‬\n         ‫وذلك بإشهار السالح األبيض على شخص وسلبه‬\n                    ‫مبلغا ماليا وجهاز جوال‬\n\n\n         ‫دعوى عامة ضد شخص الستدراجه فتاة وفعل‬\n ‫‪190‬‬                                                    ‫حرابة‬    ‫‪18‬‬\n              ‫الفاحشة بها بالقوة بعد التغرير بها‬\n\n\n           ‫دعوى عامة ضد شخصني لفعلهما الفاحشة‬\n ‫‪197‬‬                                                    ‫حرابة‬    ‫‪19‬‬\n               ‫مفاخذة بأحد األشخاص بالقوة‬\n\n\n          ‫دعوى عامة ضد وافد (مسلم غير محصن)‬\n ‫‪205‬‬     ‫بانتهاك حرمة منزل بقصد االعتداء على العرض‬      ‫حرابة‬    ‫‪20‬‬\n               ‫واغتصاب اخلادمة املنزلية بالقوة‬\n\n\n           ‫دعوى عامة ضد شخص خلطفه فتاة قاصرة‬\n ‫‪211‬‬      ‫والزنا بها حتت تهديد السالح مما أدى حلملها‬    ‫حرابة‬    ‫‪21‬‬\n                            ‫سفاحا‬\n\n\n         ‫دعوى عامة ضد شخص لترويعه اآلمنني وإخافة‬\n           ‫السبيل وذلك بإطالق النار على مجموعة من‬\n ‫‪222‬‬                                                    ‫حرابة‬    ‫‪22‬‬\n           ‫األشخاص والتسبب بإصابة بعضهم وإتالف‬\n                       ‫ممتلكات آخرين‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد شخص الشتراكه يف السطو‬\n           ‫على عدد من العمالة مبحطات الوقود حتت‬\n ‫‪239‬‬                                                   ‫حرابة‬    ‫‪23‬‬\n         ‫تهديد السالح وسلبهم والتسبب يف إصابة اثنني‬\n                            ‫منهم‬\n\n\n         ‫دعوى عامة ضد شخص إلركابه فتاة ال متت له‬\n ‫‪253‬‬                                                   ‫خطف‬      ‫‪24‬‬\n              ‫بصلة شرعية واالعتداء عليها وسبها‬\n\n\n         ‫دعوى عامة ضد شخص لقيامه باالشتراك يف‬\n ‫‪261‬‬                                                   ‫خطف‬      ‫‪25‬‬\n                 ‫محاولة خطف فتاة بالقوة‬\n\n\n           ‫دعوى عامة ضد شخص حليازته عددا من‬\n ‫‪267‬‬       ‫األوراق التي حتتوي على طالسم سحرية‬          ‫سحر‬      ‫‪26‬‬\n                ‫ومتيمتني بهما طالسم سحرية‬\n\n\n          ‫دعوى عامة ضد شخص لتوسطه يف أعمال‬\n ‫‪273‬‬      ‫السحر عن طريق النقل ألكل أموال الناس‬         ‫سحر‬      ‫‪27‬‬\n                        ‫بالباطل‬\n\n\n         ‫دعوى عامة ضد شخص لقراءته الفأل للنزالء‬\n ‫‪278‬‬                                                   ‫سحر‬      ‫‪28‬‬\n                        ‫وادعاء علم الغيب‬\n\n\n         ‫دعوى عامة ضد شخص حليازته طالسم سحرية‬\n ‫‪285‬‬                                                   ‫سحر‬      ‫‪29‬‬\n                     ‫بقصد التداوي‬\n\n\n          ‫دعوى عامة ضد شخص لتلقيه طردا يحوي‬\n ‫‪291‬‬                                                   ‫سحر‬      ‫‪30‬‬\n                 ‫أعماال سحرية لغرض سيء‬\n\f‫الصفحة‬                   ‫املوضوع‬                   ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد شخص لتهريبه طالسم سحرية‬\n ‫‪299‬‬                                                ‫سحر‬      ‫‪31‬‬\n               ‫وعلبتني بها مادة من أجل الشفاء‬\n\n\n ‫‪303‬‬      ‫دعوى عامة مبمارسة أعامل الشعوذة والدجل‬    ‫سحر‬      ‫‪32‬‬\n\n\n           ‫حيازة طالسم سحرية محتوية على امتهان‬\n ‫‪308‬‬                                                ‫سحر‬      ‫‪33‬‬\n                         ‫لكالم اهلل‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":308,"source_page_end":317,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7eddf0c70e0092af6c2416bf1fa50279602a2de6b414b54308a478fa47b677d4","normalized_text_hash":"1c31023170da9a46e48a773c8938d90fb1a72a05bd3b3b7e1834ac41aec828d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p308-34192532"},{"id":"63133570-2bb1-56fa-8453-96088e87b3dd","document_type":"judgment","category":"judicial","subcategory":"general","title":"تعويض عن سجن -املطالبة بالتعويض عن السجن لقاء دعوى كيدية -احلرمات قصاص -األصل األخذ باملثلية يف العقوبات وال يصار لغيرها إال إن تعذرت -اإلقرار يف احلق العام معتبر يف احلق اخلاص -ال يقبل الرجوع عن اإلقرار الصحيح يف احلق اخلاص .","document_number":"34182567","case_number":"3458674","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالعيص","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/8","year":"1434","subject":"تعويض عن سجن -املطالبة بالتعويض عن السجن لقاء دعوى كيدية -احلرمات قصاص -األصل األخذ باملثلية يف العقوبات وال يصار لغيرها إال إن تعذرت -اإلقرار يف احلق العام معتبر يف احلق اخلاص -ال يقبل الرجوع عن اإلقرار الصحيح يف احلق اخلاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك ‪ 34182567 :‬تاريخه‪1434/4/8 :‬هـ‬\n                        ‫رقم الدعوى‪3458674 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34238146‬تاريخه ‪1434/10/12 :‬هـ‬\n\n\n    ‫تعويــض عــن ســجن ‪ -‬املطالبــة بالتعويــض عــن الســجن لقــاء دعــوى‬\n    ‫كيديــة ‪ -‬احلرمــات قصــاص ‪ -‬األصــل األخــذ باملثليــة يف العقوبــات وال‬\n    ‫يصــار لغيرهــا إال إن تعــذرت ‪ -‬اإلقــرار يف احلــق العــام معتبــر يف احلــق‬\n     ‫اخلــاص ‪ -‬ال يقبــل الرجــوع عــن اإلقــرار الصحيــح يف احلــق اخلــاص ‪.‬‬\n\n\n\n\n                                         ‫‪ -1‬قوله تعالى‪« :‬واحلرمات قصاص»‪.‬‬\n                                   ‫‪ -2‬قوله تعالى‪« :‬وجزاء سيئة سيئة مثلها»‪.‬‬\n\n\n\n\n    ‫أقــام املدعــي اخلــاص دعــواه ضــد املدعــى عليــه بأنــه ادعــى عليــه بدعــوى‬\n    ‫كيديــة بقيامــه بإطــاق النــار وأنهــا لــم تثبــت شــرعا ممــا تســبب يف‬\n    ‫إيقافــه اثنــا عشــر يومـ ًا وطلــب إلزامــه بتعويضــه شــرعا لقــاء هــذه الفتــرة‬\n    ‫‪،‬وقــد أقــر املدعــى عليــه بأنــه ادعــى عليــه بإطــاق النــار وأن املدعــي‬\n    ‫ســجن بســبب الدعــوى اثنــا عشــر يومــا إال أنــه أنكــر بــأن دعــواه عليــه‬\n    ‫بإطــاق النــار كانــت كيديــة ‪ ،‬لــذا جــرى ســؤال املدعــي البينــة فقــرر‬\n    ‫بــأن بينتــه تنازلــه عــن دعــواه ولــو كانــت صحيحــة ملــا تنــازل عنهــا‪،‬‬\n    ‫وجــرى الرجــوع للقــرار الشــرعي فظهــر بــأن املدعــى عليــه أقر بــأن دعواه‬\n    ‫ضــد املدعــي بإطــاق النــار غيــر صحيحــة ‪ ،‬وقــرر املدعــي طلبــه املماثلــة‬\n\n‫‪5‬‬\n\f‫يف العقوبــة بحبــس املدعــى عليــه مــدة مماثلــة للمــدة التــي قضاهــا يف‬\n‫الســجن ورفــض تعويضــه ماديــا عــن املــدة التــي جــرى حبســه فيهــا ‪،‬‬\n‫وبنــاء علــى الدعــوى واإلجابــة وملــا تضمنــه القــرار الشــرعي مــن اعتــراف‬\n‫املدعــى عليــه بعــدم صحــة دعــواه ‪ ،‬وألن مــا فعلــه محــرم شــرعا ‪ ،‬ولقولــه‬\n‫تعالــى « واحلرمــات قصــاص » ‪ ،‬وقولــه تعالــى ‪ « :‬وجــزاء ســيئة ســيئة‬\n‫مثلهــا» ‪ ،‬فقــد قــررت احملكمــة احلكــم علــى املدعــى عليــه بإيقافــه‬\n‫اثنــا عشــر يوم ـ ًا للحــق اخلــاص ‪ ،‬وقــرر املدعــي القناعــة بينمــا اعتــرض‬\n‫املدعــى عليــه وقــدم الئحتــه االعتراضيــة ورفعــت القضيــة حملكمــة‬\n               ‫االســتئناف ‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا ‪ ...........‬رئيس احملكمة العامة بالعيــص وبناء‬\n‫علــى املعاملــة احملالــة لنــا برقــم ‪ 3458674‬وتاريــخ ‪ 1434/02/04‬ه ـ‬\n‫واملقيــدة باحملكمــة برقــم ‪ 34292542‬وتاريــخ ‪1434/02/04‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1434/02/19‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 30‬‬\n‫وفيهــا حضــر املدعــي ‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ...........‬وحضــر حلضــوره املدعــى عليــه ‪ ...........‬ســعودي اجلنســية‬\n‫بالســجل املدنــي رقــم ‪ ...........‬وبســؤال املدعــي عــن دعــواه قــال لقــد‬\n‫أدعــى هــذا احلاضــر يف مجلــس احلكــم علــي بدعــوى كيديــة لــم تثبــت‬\n‫حيــث اتهمنــي بإطــاق النــار عليــه ممــا تســبب يف إيقــايف اثنــي عشــر‬\n‫يومـ ًا أطلــب إلزامــه بتعويضــي لقــاء تســببه يف إيقــايف اثنــي عشــر يومـ ًا ‪-‬‬\n‫بغيــر حــق علمـ ًا بأنــه قــد حكــم عليــه فيهــا يف احلــق العــام هــذه دعــواي‬\n‫ا ‪ :‬مــا ذكــره املدعــي مــن أننــي‬‫وبعرضهــا علــى املدعــى عليــه أجــاب قائـ ً‬\n\n                                                                                      ‫‪6‬‬\n\f    ‫ادعيــت عليــه بإطــاق النــار وأنــه ســجن بســببها اثنــي عشــر يومـ ًا صحيــح‬\n    ‫ولكــن كونهــا كيديــة غيــر صحيــح فجــرى ســؤال املدعــي عــن بينتــه‬\n    ‫فقــال ‪ :‬بينتــي تنــازل املدعــي عنــي ولــو كانــت دعــواه صحيحــة لبقــي‬\n    ‫عليهــا ثــم جــرى الرجــوع إلــى القــرار الصــادر منــا باحلكــم علــى املدعــى‬\n    ‫عليــه برقــم ‪ 21‬يف ‪1433/9/12‬ه ـ واملتضمــن اعتــراف املدعــى عليــه‬\n    ‫بــأن دعــواه غيــر صحيحــة وعليــه فقــد رفعــت اجللســة للكتابــة إلــى هيئــة‬\n    ‫النظــر لتقديــر التعويــض املناســب عــن األيــام التــي أوقفهــا املدعــي وهــي‬\n    ‫اثنــا عشــر يومـ ًا ‪ -‬ويف جلســة أخــرى حضــر الطرفــان وقــد وردنــا خطــاب‬\n    ‫هيئــة النظــر رقــم ‪ ...........‬يف ‪1434/2/20‬ه ـ واملتضمــن بعــد املقدمــة أن‬\n    ‫التعويــض املناســب إليقــاف املدعــى عليــه اثنــي عشــر يوم ـ ًا ســتة آالف‬\n    ‫ريــال حيــث يقــدر اليــوم الواحــد مببلــغ وقــدره خمســمائة ريــال أ ‪ .‬ه ـ ويف‬\n    ‫هــذه اجللســة طلــب املدعــي احلكــم علــى املدعــى عليــه باإليقــاف ورفــض‬\n    ‫قبــول التعويــض ويف جلســة أخــرى حضــر الطرفــان وبنــاء علــى مــا تقــدم‬\n    ‫مــن الدعــوى واإلجابــة وبعــد االطــاع علــى القــرار املشــار إليــه أعــاه‬\n    ‫واملتضمــن اعتــراف املدعــي بعــدم صحــة دعــواه ولكــون ما فعلــه املدعى‬\n    ‫عليــه فعــل محــرم شــرع ًا ولقولــه تعالــى‪ ( :‬واحلرمــات قصــاص ) ولقولــه‬\n    ‫تعالــى‪« :‬وجــزاء ســيئة ســيئة مثلهــا» فقــد حكمــت علــى املدعــى عليــه‬\n    ‫بإيقافــه اثنــي عشــر يومـ ًا للحــق اخلــاص وبعرضــه علــى الطرفــن قنــع بــه‬\n    ‫املدعــي ولــم يقنــع املدعــى عليــه وطلــب رفعــه إلــى محكمــة االســتئناف‬\n    ‫بالئحــة وأفهــم أن عليــه تقــدمي الئحتــه خــال ثالثــن يوم ـ ًا مــن تاريــخ‬\n    ‫اســتالم الصــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/8‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/11/4‬ه ـ ويف‬\n\n\n‫‪7‬‬\n\f‫متــام الســاعة التاســعة والربــع افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة التمييــز مرفق ـ ًا بهــا القــرار رقــم ‪ 34328146‬يف‬\n‫‪1434/10/12‬ه ـ املتضمــن املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‬\n‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n                                                ‫وبــه حــرر يف ‪1434/11/4‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف يف‬\n‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n‫احملكمــة العامــة بالعيــص برقــم ‪ 34292542‬وتاريــخ ‪1434/9/8‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلتــه برقــم ‪ 34182568‬وتاريــخ‬\n‫‪1434/4/8‬ه ـ املتضمــن دعــوى ‪...................... /‬ضــد‪........... /‬يف رد‬\n‫اعتبــار احملكــوم فيــه مبــا دون باطــن القــرار وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل‬\n       ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪8‬‬\n\f9\n\f10\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":5,"source_page_end":10,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e451e7e36043851d6132c3161cb6ca323731e2705d844306ada04939f83f6328","normalized_text_hash":"90baf72708bb840f41457dd3b4b589b3a2abbc5e6f69937aa8c9783010775222","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p5-34182567"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

